import{_ as d,C as e,o,c as r,j as t,a as p,E as s,a3 as h}from"./chunks/framework.D4-ViStF.js";const y=JSON.parse('{"title":"坐忘论·简事","description":"坐忘论第四篇精读：知生有分、识事有当；权衡轻重而保全形神，不为外物耗损性命。","frontmatter":{"title":"坐忘论·简事","description":"坐忘论第四篇精读：知生有分、识事有当；权衡轻重而保全形神，不为外物耗损性命。","category":"guide","aliases":["坐忘论简事","简事四","坐忘论精读之五"],"source":["坐忘论","司马承祯"],"outline":[2,3]},"headers":[],"relativePath":"daoism/daoist-classics/zuowang-lun/chapter-04.md","filePath":"daoism/daoist-classics/zuowang-lun/chapter-04.md","lastUpdated":1789714390000}'),c={name:"daoism/daoist-classics/zuowang-lun/chapter-04.md"};function g(b,a,u,m,v,x){const i=e("DaoReadingPrelude"),n=e("DaoTextReading"),l=e("DaoKeywordCards");return o(),r("div",null,[a[0]||(a[0]=t("h1",{id:"坐忘论·简事",tabindex:"-1"},[p("坐忘论·简事 "),t("a",{class:"header-anchor",href:"#坐忘论·简事","aria-label":'Permalink to "坐忘论·简事"'},"​")],-1)),s(i,{title:"知生有分，识事有当",summary:"【收心】处理心与念头的关系；【简事】进一步调整生活的外在结构。它不是把所有事清空，而是根据生命所需、能力限度与修道目标重新决定去取——哪些必要、哪些只是欲望附加、哪些属于分内、哪些已经足够。",points:[{label:"知分",text:"生命、时间与能力都有现实限度——不务分之所无。"},{label:"识当",text:"事情各有合适的承担者与处理方式——不任事之非当。"},{label:"知足",text:"有用者取其足，多余者亦须舍；非要非重者皆应绝之。"}],hint:"此篇可与《天隐子·斋戒》对读：一个节的是食，一个简的是事，同是「去其多余、取其足用」。"}),a[1]||(a[1]=t("h2",{id:"【原典层】原文",tabindex:"-1"},[p("【原典层】原文 "),t("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),a[2]||(a[2]=t("p",null,[t("strong",null,"一、人离不开事物，却不必承担万事")],-1)),s(n,{paragraphs:["夫人之生也，必尝于事物，事物称万，不独委于一人。巢林一枝，鸟见遗于丛泊。饮河满腹，兽不吝于洪波。外求诸物，内明诸己，知生之有分，不务分之所无，识事之有当，不任事之非当。任非当，则伤于智力；务过分，则弊于形神。身且不安，何能及道。"]}),a[3]||(a[3]=t("p",null,[t("strong",null,"二、取舍：知闲要、量轻重、识去取")],-1)),s(n,{paragraphs:["是以修道之人，莫若断简事物，知其闲要，较量轻重，识其去取，非要非重，皆应绝之。犹人食有酒肉，衣有罗绮，身有名位，财有金玉，此并情欲之余好，非益生之良药。众皆徇之，自致亡败。静而思之，何迷之甚。"]}),a[4]||(a[4]=t("p",null,[t("strong",null,"三、达生：不求生命所不需要之物")],-1)),s(n,{paragraphs:["庄云：达生之情者，不务生之所无以为。生之所无以为者，分外物也。蔬食弊衣，足养性命，岂待酒肉罗绮，然后生全哉？是故于生无所要用者，并须去之。于生之用有余者，亦须舍之。"]}),a[5]||(a[5]=t("p",null,[t("strong",null,"四、以性命为重，以外物为轻")],-1)),s(n,{paragraphs:["财有害气，积则伤人，虽少犹累，而况多乎？以隋珠而弹千仞之雀，人犹笑之，况背道德，忽性命，而从非要，以自促伐者乎？","夫以名位比道德，则名位假而贱，道德真而贵。能知贵贱，应须去取，不以名害身，不以位易志。"]}),a[6]||(a[6]=t("p",null,[t("strong",null,"五、初学不可冒充「处事无累」")],-1)),s(n,{paragraphs:["庄云：行名失己，非士也。西升经云：抱元守一，过度神仙，子未能守，但坐荣官。","若不简择，触事皆为，心劳智昏，修道事阙。","若处事安闲，在物无累者，自属证成之人。若实未成，而言无累者，诚自诳耳。"]}),a[7]||(a[7]=t("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),t("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(l,{items:[{term:"必尝于事物",pinyin:["bì","cháng","yú","shì","wù"],meaning:"依底本作「尝」，文字略显不畅，或涉版本异文。按上下文理解为：人要维持生命，必然要接触、取用和处理一定的事物。"},{term:"称万",pinyin:["chēng","wàn"],meaning:"称，举其数；万，极言其多。谓世间事物多至万端。"},{term:"不独委于一人",pinyin:["bù","dú","wěi","yú","yī","rén"],meaning:"委，委任、交付、归于承担。谓天下万事不可能也不应全部交给一个人。"},{term:"巢林一枝",pinyin:["cháo","lín","yī","zhī"],meaning:"化用《庄子·逍遥游》「鹪鹩巢于深林，不过一枝」。鸟栖只需一枝，喻生命真正的需要有限。"},{term:"饮河满腹",pinyin:["yǐn","hé","mǎn","fù"],meaning:"化用《庄子·逍遥游》「偃鼠饮河，不过满腹」。与「巢林一枝」并喻知足有度的尺度。"},{term:"生之有分",pinyin:["shēng","zhī","yǒu","fèn"],meaning:"分，非宿命意义上的注定，而是生命的限度、能够承担的范围、与实际条件相称的尺度。"},{term:"识事之有当",pinyin:["shí","shì","zhī","yǒu","dàng"],meaning:"当，合宜、应当，与时机、身份、责任相称。谓辨明事情各有其合适的承担者与处理方式。"},{term:"闲要",pinyin:["xián","yào"],meaning:"闲，次要、非急需、可以放下；要，必要、紧要。知其闲要，即分清轻重缓急。"},{term:"较量轻重",pinyin:["jiào","liàng","qīng","zhòng"],meaning:"衡量价值轻重。不能只看眼前收益，也要看它消耗什么——本篇章的价值序是性命道德重于名位财货。"},{term:"余好",pinyin:["yú","hào"],meaning:"超过实际需要以后、由情欲继续追加的部分。非由物品名称机械决定，而看实际用途、数量与内心动机。"},{term:"徇",pinyin:["xùn"],meaning:"曲从、追随，甚至不惜牺牲自身。众皆徇之，谓世人普遍追逐余好而自致损伤。"},{term:"达生",pinyin:["dá","shēng"],meaning:"通达生命实情。不是知道很多养生理论，而是明白什么真正养生、什么看似享受实则伤生。语本《庄子·达生》。"},{term:"弊衣",pinyin:["bì","yī"],meaning:"朴素甚至破旧的衣服。此处表达足用原则，非要求营养不足、衣不蔽体——损害健康同样违背贵生。"},{term:"隋珠弹雀",pinyin:["suí","zhū","tán","què"],meaning:"隋珠（亦作随珠、随侯之珠）为至贵之宝，用作弹丸射高空小鸟，是以至贵换至贱。喻为外物损伤性命。"},{term:"促伐",pinyin:["cù","fá"],meaning:"促，促短、加速耗损；伐，伤害、戕害。自促伐，谓自己以错误取舍用性命换取外物。"},{term:"害气",pinyin:["hài","qì"],meaning:"财物具有牵动、耗损心气的可能。非神秘性质，而指财富引出的保管、恐惧、比较、争夺等一系列心理与事务。"},{term:"行名失己",pinyin:["xíng","míng","shī","jǐ"],meaning:"行名，以成名为行动目的；失己，失去自己。语出《庄子》。以名声为中心者，会不断根据他人目光塑造自己。"},{term:"抱元守一",pinyin:["bào","yuán","shǒu","yī"],meaning:"《西升经》语。抱元，保守生命根元；守一，使心神不散、安守道一。与「但坐荣官」相对。"},{term:"触事皆为",pinyin:["chù","shì","jiē","wéi"],meaning:"遇到任何事情都去承担。看见问题便认为自己必须解决，任何意见都想回应，任何机会都怕错过。"},{term:"修道事阙",pinyin:["xiū","dào","shì","quē"],meaning:"阙，缺失。谓修道之事被耽误缺失——事情不会自然结束，因为每件事都引出下一件，修道永远停在「以后」。"},{term:"证成",pinyin:["zhèng","chéng"],meaning:"修证已经成熟。「处事安闲，在物无累」属证成境界，是长期积习成熟后的结果，非初学口号。"}]}),a[8]||(a[8]=h(`<h2 id="【解读层】精读" tabindex="-1">【解读层】精读 <a class="header-anchor" href="#【解读层】精读" aria-label="Permalink to &quot;【解读层】精读&quot;">​</a></h2><h3 id="全篇结构与四层读法" tabindex="-1">全篇结构与四层读法 <a class="header-anchor" href="#全篇结构与四层读法" aria-label="Permalink to &quot;全篇结构与四层读法&quot;">​</a></h3><p>上一章【收心】处理心与念头的关系；本篇进一步调整生活的外在结构：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>断缘：停止以机心经营关系、谋求时利</span></span>
<span class="line"><span>收心：不让见闻、念头与毁誉占据内心</span></span>
<span class="line"><span>简事：辨别事务的必要与非必要、分内与分外</span></span></code></pre></div><p>全篇的核心原则是八个字：<strong>知生有分，识事有当。</strong></p><table tabindex="0"><thead><tr><th>层</th><th>范围（首句 → 末句）</th><th>核心问题</th></tr></thead><tbody><tr><td>一 · 事物不必一人承担</td><td>「夫人之生也」→「何能及道」</td><td>人离不开事物，为何还要简事？「分」与「当」何意？过分任事为何损伤形神？</td></tr><tr><td>二 · 分辨必要、重要与余好</td><td>「是以修道之人」→「何迷之甚」</td><td>怎样判断去取？酒肉罗绮名位金玉为何是「余好」？</td></tr><tr><td>三 · 以性命为重，外物为轻</td><td>「庄云：达生之情者」→「不以位易志」</td><td>「生之所无以为」是什么？为何有余也要舍？隋珠弹雀说明什么？</td></tr><tr><td>四 · 初学不可冒充处事无累</td><td>「庄云：行名失己」→「诚自诳耳」</td><td>「行名失己」何意？「抱元守一」与「坐荣官」如何对立？</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人必须接触事物，但天下万事不必一人承担</span></span>
<span class="line"><span>        ↓ 生命有其限度，事务有其合宜</span></span>
<span class="line"><span>任非当之事伤智力，求分外之物弊形神</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>因此必须辨别：闲与要、轻与重、去与取</span></span>
<span class="line"><span>        ↓ 非要非重者减</span></span>
<span class="line"><span>外物只应服务性命，不可反以性命追逐外物</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>名位假而贱，道德真而贵：不以名害身，不以位改志</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>初学若不简事，必然心劳智昏</span></span>
<span class="line"><span>处事无累属于证成境界，不可预先自称已经做到</span></span></code></pre></div><h3 id="一、人离不开事物-却不必承担万事" tabindex="-1">一、人离不开事物，却不必承担万事 <a class="header-anchor" href="#一、人离不开事物-却不必承担万事" aria-label="Permalink to &quot;一、人离不开事物，却不必承担万事&quot;">​</a></h3><p>「夫人之生也，必尝于事物」——依底本作「尝」，文字略显不畅，可能涉及版本异文；按上下文理解为：<strong>人要维持生命，必然要接触、取用和处理一定的事物。</strong> 修道不能完全脱离现实条件（饮食、衣服、居处、基本身体问题，也可能包括一定的家庭与社会责任）。所以本篇不是认为「事情本身都是错误」，而是承认：</p><blockquote><p><strong>生命必然有所用，只是所用应当有限、有度。</strong></p></blockquote><p>这与【断缘】篇末「若事有不可废者，不得已而行之」相承。</p><p><strong>「事物称万，不独委于一人」</strong>——这是非常重要的现实判断。人之所以事务过多，有时不是因为事情确实非做不可，而是因为：觉得只有自己能做好、害怕拒绝别人、想证明自己有能力、享受被需要的感觉、害怕错过机会、把一切问题都视为自己的责任。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>世间事务无穷，个人生命有限</span></span>
<span class="line"><span>若以有限之身承担无穷之事 → 必然形劳、心乱、智昏</span></span></code></pre></div><p><strong>这并非鼓励推卸责任，而是反对把「不属于自己的万事」都揽到身上。</strong></p><h3 id="二、「巢林一枝-饮河满腹」-生命真正需要的很有限" tabindex="-1">二、「巢林一枝，饮河满腹」：生命真正需要的很有限 <a class="header-anchor" href="#二、「巢林一枝-饮河满腹」-生命真正需要的很有限" aria-label="Permalink to &quot;二、「巢林一枝，饮河满腹」：生命真正需要的很有限&quot;">​</a></h3><p>两句化用<a href="/Dao/daoism/zhuang-zi/chapter-01">《庄子·逍遥游》</a>「鹪鹩巢于深林，不过一枝；偃鼠饮河，不过满腹」。鸟在广大森林中筑巢，只需一根树枝；兽面对浩荡河水饮水，也只需装满自己的肚腹。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>世界可以很丰富，生命所需却有自然限度</span></span></code></pre></div><p>问题不在外界事物众多，而在心是否因此产生「全部都要」的欲望：食物种类很多，不等于都要尝遍；职位机会很多，不等于都要争取；信息无限，不等于都要了解；可做之事很多，不等于都有必要承担。</p><p>真正使人劳苦的，往往不是生命实际所需，而是想象中的不足：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>身体已经足够，心却认为还不够</span></span>
<span class="line"><span>生活已经可以维持，比较又制造新的匮乏</span></span>
<span class="line"><span>一件事已经完成，好胜又要求做到更多</span></span></code></pre></div><p>所以，简事首先不是外在贫乏，而是内心知道：<strong>什么程度已经足够。</strong></p><h3 id="三、外求诸物-内明诸己" tabindex="-1">三、外求诸物，内明诸己 <a class="header-anchor" href="#三、外求诸物-内明诸己" aria-label="Permalink to &quot;三、外求诸物，内明诸己&quot;">​</a></h3><p>「外求诸物，内明诸己」——向外取得维持生命所需，同时向内明白自己的限度、能力与真正需要。这一句同时保留「外求」与「内明」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>若只有外求 → 不断被事物牵引</span></span>
<span class="line"><span>若只有内明而忽视饮食安全与责任 → 也可能损害生命</span></span></code></pre></div><p>故简事不是绝对拒物，而是：<strong>以对自身生命的明察，指导对外物的取舍。</strong>「诸己」至少需要明白四件事——自己的生命所需、能力限度、责任边界、心理动机（是在尽责，还是借任事求名）。这便引出「分」与「当」。</p><p><strong>知生之有分</strong>——「分」不能简单理解为宿命论意义的「命里注定」，而主要指生命的限度、个人能够承担的范围、实际需要的分量。「生之有分」首先是一种<strong>有限性意识</strong>：时间有限、体力有限、注意力有限、能力有边界。若不承认有限，就会用有限生命追逐无限对象，最终必然耗损。「不务分之所无」的「务」比普通接触更强，指全力经营、刻意求取；所谓「分外物」，还包括超过生命实际需要的占有、超过自身能力的事务、不属于自己责任的控制、仅因别人拥有而想要的追问。</p><p><strong>识事之有当</strong>——「当」指合宜、应当、与时机身份责任相称。「知分」主要从人的承受限度说，「识当」则主要从事情本身的合理归属说：</p><table tabindex="0"><thead><tr><th>原则</th><th>所问的问题</th></tr></thead><tbody><tr><td>知生有分</td><td>我能承担多少？我真正需要多少？</td></tr><tr><td>识事有当</td><td>这件事应不应该由我做？现在是否应该做？</td></tr></tbody></table><p>一件事即使有价值，也未必此时必须做、必须由自己做、必须做到最大规模。可以形成三类：</p><table tabindex="0"><thead><tr><th>事务类型</th><th>处理方式</th></tr></thead><tbody><tr><td>分内且必要</td><td>应当完成</td></tr><tr><td>有益但可由他人承担</td><td>不必独揽</td></tr><tr><td>非时、非事、超出分限</td><td>应当舍弃</td></tr></tbody></table><h3 id="四、「任非当」与「务过分」的不同损害" tabindex="-1">四、「任非当」与「务过分」的不同损害 <a class="header-anchor" href="#四、「任非当」与「务过分」的不同损害" aria-label="Permalink to &quot;四、「任非当」与「务过分」的不同损害&quot;">​</a></h3><p><strong>任非当，则伤于智力</strong>——非当之事为什么首先伤「智力」？因为要不断处理本不属于自己的问题，心便被迫进行大量额外计算（协调、判断、解释、预测、防备、维持、收拾后果）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任事过多 → 心神不断切换 → 注意力耗散 → 判断能力下降 → 应做之事反而不能做好</span></span></code></pre></div><p>这与【收心】「小事关心，心必动乱」相应。</p><p><strong>务过分，则弊于形神</strong>——「务过分」比「任非当」更深一步：不只是事务太多，而是欲望没有限度（已有足够财富仍不断积累、已经完成责任仍追求完美控制、身体已经疲惫仍不肯停止）。结果是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>外物增加 → 维护成本增加 → 忧虑与劳作增加 → 形体疲惫 → 精神耗散</span></span></code></pre></div><p>所以，简事不是为了提高效率后承担更多，而是为了<strong>真正减少不必要的消耗</strong>。</p><p><strong>身且不安，何能及道</strong>——《坐忘论》并不把修心与现实身心状态完全分开。若睡眠严重不足、事务始终过量、每日处于急迫状态，就很难稳定地收心、真观与入定。<strong>简事不是修道之外的生活管理，而是进入定慧的必要条件。</strong></p><h3 id="五、怎样进行取舍" tabindex="-1">五、怎样进行取舍 <a class="header-anchor" href="#五、怎样进行取舍" aria-label="Permalink to &quot;五、怎样进行取舍&quot;">​</a></h3><p><strong>莫若断简事物</strong>——「断简」是两个动作：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>断：对于明显妨道、毫无必要之事，停止它</span></span>
<span class="line"><span>简：对于不能完全废除之事，减少其数量与复杂程度</span></span></code></pre></div><p>有些应立即停止，有些应逐渐减少，有些需保留，有些可转交他人——这比简单说「什么都不要」更有层次。</p><p><strong>知其闲要</strong>——「闲」不等于完全没有价值，而是相对于当前生命与修道而言不必优先处理。一件事可能有趣却不必要、有益却不紧要、可以做却不必现在做。<strong>能够承认「可做而不必做」，是简事的重要能力。</strong></p><p><strong>较量轻重</strong>——比较轻重时，不能只看眼前收益，也要看它消耗什么：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>获得一项名利，是否要以长期心神不安为代价？</span></span>
<span class="line"><span>增加一项事务，是否会挤压休息与修道时间？</span></span>
<span class="line"><span>追求更高成就，是否会损害身体与基本责任？</span></span></code></pre></div><p><strong>识其去取</strong>——仅仅知道一件事不重要，还不等于真正能舍；简事最终必须落实到选择：不接受某些邀请、不承担额外任务、降低对某些目标的投入、给事务设定完成边界。「去取」正是敬信落实到行动的地方。</p><p><strong>非要非重，皆应绝之</strong>——第一重筛选：「是否必要？是否重要？二者皆否→应当舍弃。」但「重要」不能由社会热度、他人评价或个人虚荣决定，而应从性命与道德判断。</p><h3 id="六、酒肉、罗绮、名位、金玉为何都是「余好」" tabindex="-1">六、酒肉、罗绮、名位、金玉为何都是「余好」 <a class="header-anchor" href="#六、酒肉、罗绮、名位、金玉为何都是「余好」" aria-label="Permalink to &quot;六、酒肉、罗绮、名位、金玉为何都是「余好」&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>例子</th></tr></thead><tbody><tr><td>饮食</td><td>酒肉</td></tr><tr><td>衣服</td><td>罗绮</td></tr><tr><td>社会身份</td><td>名位</td></tr><tr><td>财物</td><td>金玉</td></tr></tbody></table><p>这些并非生命完全不能接触之物，而是相对于基本需要而言的附加享受，故称「<strong>情欲之余好，非益生之良药</strong>」。「余好」不是一切正常喜好，而是超过实际需要以后由情欲继续追加的部分：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>因饥饿而进食 → 性命所需</span></span>
<span class="line"><span>在营养健康范围内有所选择 → 正常生活</span></span>
<span class="line"><span>明知身体已足，仍为刺激不断追求 → 情欲余好</span></span>
<span class="line"><span></span></span>
<span class="line"><span>衣能御寒蔽体 → 必需</span></span>
<span class="line"><span>衣求华美以证明身份 → 余好</span></span>
<span class="line"><span>职位用于履行责任 → 有当</span></span>
<span class="line"><span>职位用于满足优越与控制 → 余好</span></span></code></pre></div><p>所以余好与必要并非由物品名称机械决定，而要看<strong>实际用途、数量和内心动机</strong>。「非益生之良药」是比喻：生命真正需要的是饮食适度、衣服适宜、居处安全、身心调和、事务不过量；酒肉华服名位金玉或许带来暂时满足，却不能解决生命根本问题——若反过来为它们劳神伤身，就成了「以养生之物害生」。</p><p><strong>「众皆徇之，自致亡败」</strong>——揭示从众的力量：许多欲望不是生命自然需要，而是比较产生（别人拥有所以我也需要、社会认为名位重要所以我不能舍）。这与总论「喜色味为得志，鄙恬素为穷辱」相应。</p><p><strong>「静而思之，何迷之甚」</strong>——说明简事并非反对一切思考，而是要求用清明思考重新检查生活：这真是生命所需吗？收益是否值得相应消耗？我是在使用外物，还是已被外物役使？<strong>【收心】使心静下来，【简事】则运用这种清静重新判断轻重。</strong></p><h3 id="七、「达生」就是不求生命所不需要之物" tabindex="-1">七、「达生」就是不求生命所不需要之物 <a class="header-anchor" href="#七、「达生」就是不求生命所不需要之物" aria-label="Permalink to &quot;七、「达生」就是不求生命所不需要之物&quot;">​</a></h3><p>《庄子·达生》通行本有「达生之情者，不务生之所无以为；达命之情者，不务知之所无奈何」，「情」指实情。<strong>真正通达生命实情的人，不会追求生命本来不需要的东西。</strong>「达生」不是知道很多养生理论，而是明白什么真正养生、什么看似享受实则伤生。</p><p>「生之所无以为者，分外物也」——不是说它绝对不能用，而是：<strong>没有它，生命仍能成立。</strong> 既然生命不依赖它，就不应为了它反过来伤害生命。</p><p>「蔬食弊衣，足养性命」表达的是古代出家修道者的简素标准。现代阅读不必机械模仿「衣服越破越好」，重点在于：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>衣食的基本功能 重于 借衣食展示身份</span></span></code></pre></div><p>衣服若已不能保暖、饮食若营养不足，反而损害生命——<strong>本篇提倡的是「足用」，不是自我虐待。</strong> 「岂待酒肉罗绮，然后生全哉」切断的正是这个错误等式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生活奢华 ≠ 生命完整；感官满足 ≠ 性命得到保全</span></span></code></pre></div><h3 id="八、不仅「无用」要去-「有余」也要舍" tabindex="-1">八、不仅「无用」要去，「有余」也要舍 <a class="header-anchor" href="#八、不仅「无用」要去-「有余」也要舍" aria-label="Permalink to &quot;八、不仅「无用」要去，「有余」也要舍&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>于生无所要用者，并须去之：去掉无用、非必要之物</span></span>
<span class="line"><span>于生之用有余者，亦须舍之：确实有用但已超过所需，也应舍去多余部分</span></span></code></pre></div><p>有些东西不是完全无用（金钱有生活用途、工具有工作用途），问题在于「有余」：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有用 ≠ 越多越好</span></span>
<span class="line"><span>足够以后继续增加 → 产生新的保管、维护、比较和焦虑</span></span></code></pre></div><p>所以本篇不是简单的「有用主义」，而是<strong>足用原则</strong>：</p><blockquote><p><strong>有用者取其足，无用者去之，多余者舍之。</strong></p></blockquote><table tabindex="0"><thead><tr><th>情况</th><th>原则</th></tr></thead><tbody><tr><td>对生命、责任皆无必要</td><td>去除</td></tr><tr><td>有一定用途，但已过量</td><td>舍去多余</td></tr><tr><td>确属必要、数量适度</td><td>保留使用</td></tr></tbody></table><p><strong>这正是「简事」，而不是「灭事」。</strong></p><h3 id="九、「财有害气-积则伤人」" tabindex="-1">九、「财有害气，积则伤人」 <a class="header-anchor" href="#九、「财有害气-积则伤人」" aria-label="Permalink to &quot;九、「财有害气，积则伤人」&quot;">​</a></h3><p>这不是说财物具有某种必然伤人的神秘性质，而是说财富积聚会引出一系列心理和事务：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>获得财物 → 需要保管 → 财物增加 → 害怕失去 → 加强防备和经营 → 心气越受扰动</span></span></code></pre></div><p>还可能引出比较、争夺、猜疑、身份依赖、对未来损失的恐惧。故「害气」的关键仍在<strong>财物与心的关系</strong>。「虽少犹累，而况多乎」语气较严格，符合出家修道者的语境；现代阅读需区分：为基本生活保留必要资源（必要储备可以减少不安）与因恐惧贪欲而无限积累（越怕失去越要积累）。<strong>本篇真正反对的不是数字意义上的财富，而是「财物由生活工具变成心神主人」。</strong></p><h3 id="十、「隋珠弹雀」-不要用至贵追逐轻贱" tabindex="-1">十、「隋珠弹雀」：不要用至贵追逐轻贱 <a class="header-anchor" href="#十、「隋珠弹雀」-不要用至贵追逐轻贱" aria-label="Permalink to &quot;十、「隋珠弹雀」：不要用至贵追逐轻贱&quot;">​</a></h3><p>底本作「隋珠」，通常亦写作「随珠」，指珍贵无比的宝珠。此典常以「所用者重，所要者轻」说明价值失衡：</p><table tabindex="0"><thead><tr><th>譬喻</th><th>所指</th></tr></thead><tbody><tr><td>隋珠</td><td>性命与道德</td></tr><tr><td>千仞之雀</td><td>名位、财货与欲望余好</td></tr><tr><td>以珠弹雀</td><td>为轻贱外物损伤宝贵性命</td></tr></tbody></table><p>人不是被外物单方面伤害，而是因为错误取舍，主动用性命换取外物——<strong>这就是现代形式的「随珠弹雀」</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>以睡眠换名利 / 以健康换地位 / 以心安换财货 / 以道德换机会 / 以自由换无穷占有</span></span></code></pre></div><h3 id="十一、名位与道德-何者真-何者假" tabindex="-1">十一、名位与道德：何者真，何者假 <a class="header-anchor" href="#十一、名位与道德-何者真-何者假" aria-label="Permalink to &quot;十一、名位与道德：何者真，何者假&quot;">​</a></h3><p>「名位假而贱，道德真而贵」——「假」不是说名位根本不存在，而是说它「假借众缘」才成立（需要制度承认、他人评价、特定环境，且会随时代与关系变化；人离开职位，名位可能随即消失）。道德则主要表现为心是否清静、行为是否合宜、是否不以机心伤人、是否不因得失改变志向。所以「真假」主要是<strong>依存方式和稳定程度</strong>的区别：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>名位依外而立 → 条件一变便会改变</span></span>
<span class="line"><span>道德由内而成 → 不完全取决于别人承认</span></span></code></pre></div><p>「能知贵贱，应须去取」——知道道德比名位重要，却每逢冲突都牺牲道德保全名位，这种「知」尚未成为真实知见。真正的知贵贱应表现为：名位不伤道，可以因事承担；名位与道相冲突，宁守道而舍位。</p><p>「不以名害身，不以位易志」——分别指出名位的两种危险：</p><ul><li><strong>名害身</strong>：为名声过度任事、耗损身体、不能承认自己的限度、明知疲惫仍要维持形象；</li><li><strong>位易志</strong>：为地位改变原有原则、曲意迎合、不敢说真实判断、把角色利益置于道德之上。</li></ul><p><strong>简事不是否定一切名位，而是不允许名位成为损身易志的力量。</strong></p><h3 id="十二、「行名失己」与「抱元守一」" tabindex="-1">十二、「行名失己」与「抱元守一」 <a class="header-anchor" href="#十二、「行名失己」与「抱元守一」" aria-label="Permalink to &quot;十二、「行名失己」与「抱元守一」&quot;">​</a></h3><p><strong>「行名失己，非士也」</strong>——「行名」不是正常行动获得名声，而是以成名为行动目的。当名声成为中心，人会不断根据他人目光塑造自己（别人称赞什么便表现什么、害怕失去形象便掩饰过错、为了维护名声逐渐失去本志），这就是「失己」。</p><p>与【敬信】「怀宝求宝」相比，二者共同揭示向外追逐的悖论：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>本来有心性之宝，却向外求评价</span></span>
<span class="line"><span>越向外经营名声，越远离自身本根</span></span></code></pre></div><p><strong>《西升经》「抱元守一，过度神仙，子未能守，但坐荣官」</strong>——</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>抱元守一：心神内敛，不为万事耗散，趋向道与神仙</span></span>
<span class="line"><span>但坐荣官：心系名位，事务繁兴，被外在身份固定</span></span></code></pre></div><p>「坐荣官」并不是说做官必然不能修道，而是说若心安住于官位荣耀、把它当作生命归宿，便无法守一。心为什么不能守一？原因之一就是事务过多：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事多 → 心分 → 神散 → 不能守一</span></span></code></pre></div><p><strong>所以简事的目的不是单纯获得空闲，而是保护心神的统一性。</strong></p><h3 id="十三、若不简择-为什么「心劳智昏」" tabindex="-1">十三、若不简择，为什么「心劳智昏」 <a class="header-anchor" href="#十三、若不简择-为什么「心劳智昏」" aria-label="Permalink to &quot;十三、若不简择，为什么「心劳智昏」&quot;">​</a></h3><p>「触事皆为」是本篇批评的典型状态：看见问题便认为自己必须解决、收到邀请便觉得不能拒绝、遇到机会便害怕错过、任何意见都想回应、任何知识都想了解。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>事务数量增加 → 注意力不断切换 → 心神长期疲劳</span></span>
<span class="line"><span>        → 判断力下降 → 应做之事也做不好 → 修道永远被排到最后</span></span></code></pre></div><p>「修道事阙」尤其值得注意。人可能总说：</p><blockquote><p>等这些事情结束，我再安坐收心。</p></blockquote><p>但<strong>如果没有简择，事情不会自然结束，因为每件事情都会引出下一件事情</strong>。修道于是永远停留在「以后」。</p><h3 id="十四、「处事安闲」属于证成-不是初学口号" tabindex="-1">十四、「处事安闲」属于证成，不是初学口号 <a class="header-anchor" href="#十四、「处事安闲」属于证成-不是初学口号" aria-label="Permalink to &quot;十四、「处事安闲」属于证成，不是初学口号&quot;">​</a></h3><p>「若处事安闲，在物无累者，自属证成之人」——司马承祯并不否认存在这种境界（这正是【收心】篇末所承认的「在物而不染，处事而不乱」）。证成之人的状态是：事情来时清楚处理、事情去后不留于心、身在名位而不以名位为己、能承担事务而不显德露能、能使用智慧而不以智害恬。<strong>但这是长期积习成熟后的结果。</strong></p><p>「若实未成，而言无累者，诚自诳耳」——怎样判断自己是否「实未成」？可以观察：</p><ul><li>遇到毁誉是否立刻动心？</li><li>事情结束后是否反复回想？</li><li>失去名位时是否强烈不安？</li><li>是否以「我不执著」为由不断增加事务？</li><li>是否表面无累，实际身心已经疲惫？</li></ul><p>若这些现象仍然明显，就应承认自己尚在训练阶段，而不是借最高境界取消基础练习。</p><p>两者的关系是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>处事不乱：最终能力</span></span>
<span class="line"><span>简事收心：形成这种能力的过程</span></span></code></pre></div><h3 id="十五、简事不是「效率管理」" tabindex="-1">十五、简事不是「效率管理」 <a class="header-anchor" href="#十五、简事不是「效率管理」" aria-label="Permalink to &quot;十五、简事不是「效率管理」&quot;">​</a></h3><p>现代人容易把【简事】理解成提高生产效率——这只理解了一半。《坐忘论》的目标不是通过简化让人承担更多、获得更多，而是：</p><blockquote><p><strong>减少外事对形神的占用，为归根、静定与真观保存生命条件。</strong></p></blockquote><table tabindex="0"><thead><tr><th>效率式简化</th><th>《坐忘论》的简事</th></tr></thead><tbody><tr><td>省时以做更多</td><td>省事以保养形神</td></tr><tr><td>追求更大产出</td><td>追求合宜与足够</td></tr><tr><td>仍以成就为中心</td><td>以性命与道德为重</td></tr><tr><td>淘汰低效事项</td><td>舍弃非要、非重之事</td></tr><tr><td>可能继续扩大目标</td><td>有意识地承认限度</td></tr></tbody></table><p><strong>简事的终点不是「高效繁忙」，而是「事称其分，心有余闲」。</strong></p><h3 id="十六、简事的三重判断法" tabindex="-1">十六、简事的三重判断法 <a class="header-anchor" href="#十六、简事的三重判断法" aria-label="Permalink to &quot;十六、简事的三重判断法&quot;">​</a></h3><p><strong>第一层：要不要做？</strong> 它是否关系基本生活？是否属于不可废的责任？是否真正有益于性命和道德？若不做会有什么实际后果？——若非要非重，可以舍弃。</p><p><strong>第二层：应不应该由我做？</strong> 是否属于我的分内？是否可以由更合适的人承担？我是否因害怕拒绝而揽事？是否借承担事务证明自己的重要？——若属「事之非当」，不应独任。</p><p><strong>第三层：做到多少才足够？</strong> 完成基本责任以后，是否还在不断追加？更多投入是否仍有真实收益？是否已经开始损害身体与心神？——即使有用，超过所需也应减少。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>非必要 → 去之</span></span>
<span class="line"><span>非我所当 → 不任</span></span>
<span class="line"><span>虽有用而过量 → 舍其有余</span></span>
<span class="line"><span>确属必要且适量 → 如理完成，事毕即止</span></span></code></pre></div><h3 id="引经据典" tabindex="-1">引经据典 <a class="header-anchor" href="#引经据典" aria-label="Permalink to &quot;引经据典&quot;">​</a></h3><table tabindex="0"><thead><tr><th>书中引文／典故</th><th>出处</th><th>作用</th></tr></thead><tbody><tr><td>巢林一枝，饮河满腹</td><td><a href="/Dao/daoism/zhuang-zi/chapter-01">《庄子·逍遥游》</a></td><td>世界丰富而生命所需有自然限度，是「知足够用」的尺度</td></tr><tr><td>达生之情者，不务生之所无以为</td><td>《庄子·达生》</td><td>「简事」最重要的理论依据：通达生命实情者不求其不需要之物</td></tr><tr><td>隋珠弹雀</td><td>典出《庄子》相关思想传统</td><td>以「所用者重、所要者轻」说明以性命逐外物的价值失衡</td></tr><tr><td>行名失己，非士也</td><td>《庄子》</td><td>以成名为行动目的者，会失去自己</td></tr><tr><td>抱元守一，过度神仙，子未能守，但坐荣官</td><td>《西升经》</td><td>「守一」与「坐荣官」两种人生方向的对立</td></tr></tbody></table><p>逐条的原典语境与考订见<a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">《引经据典》</a>。</p><h3 id="与《天隐子》的对应" tabindex="-1">与《天隐子》的对应 <a class="header-anchor" href="#与《天隐子》的对应" aria-label="Permalink to &quot;与《天隐子》的对应&quot;">​</a></h3><table tabindex="0"><thead><tr><th>《天隐子》</th><th>本篇</th><th>呼应</th></tr></thead><tbody><tr><td>斋戒四（节食调中，食勿令饱）</td><td>蔬食弊衣足养性命／酒肉罗绮为余好</td><td>共同关心衣食是否服务于生命，而非役使生命</td></tr><tr><td>安处五（调风气明暗，心目皆安）</td><td>简事（减少事务之扰）</td><td>安处整理空间环境，简事整理事务环境，皆为收心创造条件</td></tr><tr><td>易简二（至道不繁，反对奇诡）</td><td>简事（不求分外、不任非当、不逐余好）</td><td>真正的「易简」不仅是方法简单，也是生活不被无穷欲望复杂化</td></tr><tr><td>存想六（终日接他事，故目亦逐外瞻）</td><td>简事（从源头减少接他事）</td><td>事务不简则心目不断逐外；事务得简，才有余地返照形神</td></tr><tr><td>坐忘七（遗形忘我）</td><td>由取舍而至忘取舍</td><td>初学有意识地舍非要取所当；纯熟后欲望自然淡薄；最终连「我正在舍物修道」的意识也淡化</td></tr></tbody></table><h3 id="容易误解的地方" tabindex="-1">容易误解的地方 <a class="header-anchor" href="#容易误解的地方" aria-label="Permalink to &quot;容易误解的地方&quot;">​</a></h3><ol><li><strong>简事不是完全不做事</strong>——本篇说「不任事之非当」，反过来也承认「当做之事」应当承担；重点是有选择、有边界。</li><li><strong>「知分」不是宿命主义</strong>——不是要求人永远停留在某种社会位置，而是承认时间、体力、注意力和责任都有现实限度。</li><li><strong>朴素不等于自我虐待</strong>——「蔬食弊衣」表达足用原则，不是要求故意营养不足、衣不蔽体；损害健康同样违背贵生。</li><li><strong>财物并非绝对邪恶</strong>——财物是生活工具；当它引发无穷积聚、恐惧和争夺时，才成为「害气」之累。</li><li><strong>名位也不是绝对不可承担</strong>——问题在于是否以名害身、以位易志、是否把名位当作固定自我。</li><li><strong>「有余则舍」不能成为对他人的强制</strong>——每个人的实际责任、身体条件与生活处境不同；简事首先是反观自身，而不是用自己的简朴标准评判所有人。</li><li><strong>不能以「在物无累」为由无限加事</strong>——判断是否无累，不看口头自称，而看身体是否安稳、心是否仍受毁誉得失扰动、事情结束后是否能放下、定慧是否因事务而中断。</li></ol><h3 id="现实修养练习" tabindex="-1">现实修养练习 <a class="header-anchor" href="#现实修养练习" aria-label="Permalink to &quot;现实修养练习&quot;">​</a></h3><p>把当前事务分为四栏：</p><table tabindex="0"><thead><tr><th>类别</th><th>特征</th><th>原则</th></tr></thead><tbody><tr><td>必要且分内</td><td>关系生活、责任与承诺</td><td>如理完成</td></tr><tr><td>重要但可分担</td><td>有价值，但不必独自承担</td><td>合理分工</td></tr><tr><td>有用但过量</td><td>已超过实际需要</td><td>减少余量</td></tr><tr><td>非要非重</td><td>由虚荣、比较或惯性维持</td><td>停止或渐退</td></tr></tbody></table><p>对每件长期占据心神的事，可以问：</p><ol><li>如果没有他人的目光，我还会做它吗？</li><li>它属于生命所需，还是情欲余好？</li><li>它真的必须由我承担吗？</li><li>做到什么程度就已经足够？</li><li>它带来的利益，是否值得形神上的消耗？</li><li>我是在使用名位财物，还是已经被它们役使？</li><li>舍弃它损失的是生命根本，还是仅仅损失某种形象？</li></ol><p>这些问题，就是「知其闲要，较量轻重，识其去取」的现代实行。</p><h3 id="完整路线图" tabindex="-1">完整路线图 <a class="header-anchor" href="#完整路线图" aria-label="Permalink to &quot;完整路线图&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>人要生存，必然需要一定事物</span></span>
<span class="line"><span>        ↓ 但世间万事不必一人承担</span></span>
<span class="line"><span>鸟巢不过一枝，兽饮不过满腹：生命真实所需原本有限</span></span>
<span class="line"><span>        ↓ 向外取物，也要向内明己</span></span>
<span class="line"><span>知生有分 → 不求分外之物</span></span>
<span class="line"><span>识事有当 → 不任非当之事</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>任非当则伤智力，务过分则弊形神</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>因此必须：知闲要、量轻重、识去取</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>非要非重者断；有用而过量者减；必要而适度者留</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>衣食财位只是养生之具，不可变成情欲余好</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>性命如隋珠，名利如高空之雀——不可用至贵追逐轻贱</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>名位假而贱，道德真而贵：不以名害身，不以位易志</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>若触事皆为，必然心劳智昏、修道事阙</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>处事安闲、在物无累属于证成境界</span></span>
<span class="line"><span>初学若未成而自称无累，只是自我欺骗</span></span></code></pre></div><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h3><p>【简事】并不是否定现实生活，而是为现实事务建立尺度：</p><blockquote><p><strong>生命有所需，却不需要万物；个人有所当，却不应承担万事。</strong></p></blockquote><p>四项判断：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>知分：承认生命、时间与能力有限</span></span>
<span class="line"><span>识当：辨别事情是否应由自己承担</span></span>
<span class="line"><span>量重：以性命、道德重于名位财货</span></span>
<span class="line"><span>知足：有用者取其足，多余者亦须舍</span></span></code></pre></div><p>最尖锐的警告是「隋珠弹雀」：</p><blockquote><p><strong>性命与道德是至贵之珠，名位财货只是相对轻微之外物；若为了轻物耗损形神，就是以重求轻、以贵换贱。</strong></p></blockquote><p>而全篇最后又回到修道次第：<strong>证成之人可以处事安闲、在物无累；初学者若尚受事务扰动，却借此境界拒绝简事，只是自欺。</strong></p><p>所以本篇可以浓缩为一句话：</p><blockquote><p><strong>简事不是把人生缩减成空白，而是舍去非要、非重、非当与过量之事，使有限的形神回到真正重要的性命与大道。</strong></p></blockquote><p>经过【断缘】，不再以机心结交；经过【收心】，不再随见闻流浪；经过【简事】，又从现实结构上减少了形神负担。下一篇<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-05">《真观》</a>便要进一步追问：即使外缘已断、事务已简，内心为什么仍会对色欲、贫病、毁誉、生死产生执著？又应怎样从根本上观察它们？</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/daoism/daoist-classics/zuowang-lun/">《坐忘论》总览</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/guide">全书引读</a> · <a href="/Dao/daoism/daoist-classics/zuowang-lun/classics">引经据典</a></li><li>上一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-03">收心三</a> · 下一篇：<a href="/Dao/daoism/daoist-classics/zuowang-lun/chapter-05">真观五</a></li><li>引文出处：<a href="/Dao/daoism/zhuang-zi/chapter-01">《庄子·逍遥游》</a>（巢林一枝、饮河满腹）、《庄子·达生》（达生之情者）、《西升经》（抱元守一）</li><li>《天隐子》对应：<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-4">斋戒四</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-5">安处五</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-2">易简二</a>、<a href="/Dao/daoism/daoist-classics/tianyinzi#pian-6">存想六</a></li></ul>`,145))])}const q=d(c,[["render",g]]);export{y as __pageData,q as default};
